<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import { t, locale, setLocale } from './i18n'
import TerminalPanel from './TerminalPanel.vue'
type Node = { serial:string;created_at:string;stage:string;error:string;headscale_id:string;headscale_state:string;headscale_seen:string;addresses:string;mesh_id:string;mesh_state:string;mesh_seen:string;mesh_url:string }
type Token = { id:string;label:string;expires_at:string;max_uses:number;uses:number;revoked:boolean }
type Agent = {online:boolean;revoked:boolean;last_seen:string;ssh_configured:boolean;info:{os_version:string;os:string;arch:string;version:string;uptime_seconds:number}}
type Audit = {id:string;serial:string;actor:string;created_at:string;started_at:string;ended_at:string;reason:string}
const bootstrapAvailable=ref(false)
const installCommand=computed(()=>`curl --fail --silent --show-error --proto '=https' --tlsv1.2 '${location.origin}/install.sh' | bash -s -- --server '${location.origin}' --prepare-image`)
const copied=ref(false)
async function copyInstallCommand(){try{await navigator.clipboard.writeText(installCommand.value);copied.value=true}catch{error.value=t('Copy failed; select and copy the command manually.')}}
const agents=ref<Record<string,Agent>>({}), terminalEnabled=ref(false), terminalNode=ref(''), audit=ref<Audit[]>([])
type Source = {source:string;state:string;last_success:string;error:string}
const ready=ref(false), logged=ref(false), authEnabled=ref(true), busy=ref(false), error=ref(''), tab=ref('nodes'), query=ref('')
const username=ref('admin'), password=ref(''), nodes=ref<Node[]>([]), tokens=ref<Token[]>([]), sources=ref<Source[]>([]), selected=ref<Node|null>(null)
const interval=ref(60), meshURL=ref(''), lastRefresh=ref(''), tokenLabel=ref(''), expiry=ref(''), maxUses=ref(0), secret=ref(''), meshID=ref('')
let timer:ReturnType<typeof setTimeout>|undefined
async function api<T>(path:string, body?:unknown):Promise<T> {
 const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-NodeHub-Request':'1'},...(body===undefined?{}:{body:JSON.stringify(body)})})
 const data=await r.json();if(!r.ok){if(r.status===401){logged.value=false;secret.value='';terminalNode.value=''}throw Error(data.error||'Request failed')};return data
}
async function refresh(){
 if(busy.value||!logged.value)return;busy.value=true
 try{const [n,t,s,g,history]=await Promise.all([api<Node[]>('/nodes'),api<Token[]>('/tokens'),api<{sources:Source[];poll_interval_seconds:number;meshcentral_url:string;bootstrap_available?:boolean}>('/status'),api<{enabled:boolean;nodes:Record<string,Agent>}>('/agents'),api<Audit[]>('/terminal-audit')]);nodes.value=n;tokens.value=t;agents.value=g.nodes;terminalEnabled.value=g.enabled;audit.value=history;sources.value=s.sources;interval.value=s.poll_interval_seconds;meshURL.value=s.meshcentral_url;bootstrapAvailable.value=!!s.bootstrap_available;lastRefresh.value=new Date().toLocaleTimeString(locale.value);if(selected.value)selected.value=n.find(x=>x.serial===selected.value?.serial)||null;error.value=''}catch(e){error.value=String((e as Error).message)}finally{busy.value=false}
}
async function tick(){await refresh();timer=setTimeout(tick,interval.value*1000)}
async function login(){try{await api('/login',{username:username.value,password:password.value});password.value='';logged.value=true;error.value='';await refresh()}catch(e){error.value=(e as Error).message}}
async function logout(){terminalNode.value='';try{await api('/logout',{});logged.value=false;nodes.value=[];tokens.value=[];selected.value=null;secret.value=''}catch(e){error.value=(e as Error).message}}
async function createToken(){try{const r=await api<{secret:string}>('/tokens',{label:tokenLabel.value,expires_at:expiry.value?new Date(expiry.value).toISOString():'',max_uses:maxUses.value});secret.value=r.secret;tokenLabel.value='';await refresh()}catch(e){error.value=(e as Error).message}}
async function revoke(token:Token){if(!confirm(t('Revoke {name}? Copies of this token in other images will also stop working.', {name: token.label||token.id})))return;try{await api(`/tokens/${token.id}/revoke`,{});await refresh()}catch(e){error.value=(e as Error).message}}
async function bind(){if(!selected.value||!meshID.value)return;if(!confirm(t('Confirm this external device ID belongs to this node? The binding will not be replaced automatically.')))return;try{await api(`/nodes/${selected.value.serial}/meshcentral-bind`,{node_id:meshID.value});meshID.value='';await refresh()}catch(e){error.value=(e as Error).message}}
const filtered=computed(()=>nodes.value.filter(n=>[n.serial,n.addresses].some(s=>s.toLowerCase().includes(query.value.toLowerCase()))))
const online=computed(()=>nodes.value.filter(n=>n.headscale_state==='online'||n.mesh_state==='online'||agents.value[n.serial]?.online).length)
const unfinished=computed(()=>nodes.value.filter(n=>n.stage!=='complete').length)
const labels:Record<string,string>={online:'Online',offline:'Offline',unknown:'Unknown',missing:'Not found upstream',ok:'Sync healthy',error:'Sync failed',disabled:'Not configured',registered:'Registered',hostname_ready:'Hostname configured',tailscale_ready:'Network registered',mesh_ready:'Remote management installed',awaiting_binding:'Awaiting device binding',awaiting_overlay:'Awaiting finalization',complete:'Initialization complete',failed:'Initialization failed'}
const text=(s:string)=>t(labels[s]||s)
const date=(s:string)=>s?new Date(s).toLocaleString(locale.value):'—'
async function revokeAgent(serial:string){if(!confirm(t('Revoke this Node Hub Agent and close its terminals? Headscale and MeshCentral access will remain active.')))return;try{await api(`/nodes/${serial}/agent-revoke`,{});if(terminalNode.value===serial)terminalNode.value='';await refresh()}catch(e){error.value=(e as Error).message}}
function safeURL(s:string){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?s:undefined}catch{return undefined}}
onMounted(async()=>{try{const s=await api<{auth_enabled:boolean}>('/session');authEnabled.value=s.auth_enabled;logged.value=true}catch{}finally{ready.value=true;await tick()}})
onUnmounted(()=>{if(timer)clearTimeout(timer)})
</script>

<template>
 <div class="language-switch"><label>{{ t('Language') }} <select :value="locale" @change="setLocale(($event.target as HTMLSelectElement).value)"><option value="en">English</option><option value="zh-CN">简体中文</option></select></label></div>
 <div v-if="!ready" class="loading">{{ t('Connecting to Node Hub…') }}</div>
 <main v-else-if="!logged" class="login-page">
  <form class="login-card" @submit.prevent="login"><div class="brand-mark">N</div><p class="eyebrow">NODE HUB</p><h1>{{ t('Connect every node') }}</h1><p class="muted">{{ t('Sign in to the management console') }}</p><label>{{ t('Username') }}<input v-model="username" autocomplete="username" required></label><label>{{ t('Password') }}<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" role="alert" class="error">{{t(error)}}</p><button class="primary">{{ t('Sign in →') }}</button></form>
 </main>
 <div v-else class="shell">
  <aside><div class="brand"><span class="brand-mark">N</span><div>{{ t('Node Hub') }}<small>{{ t('Edge node management') }}</small></div></div><nav><button :class="{active:tab==='nodes'}" @click="tab='nodes'">{{ t('▦') }} <span>{{ t('Node overview') }}</span><small>{{nodes.length}}</small></button><button :class="{active:tab==='tokens'}" @click="tab='tokens'">{{ t('⌘') }} <span>{{ t('Enrollment tokens') }}</span></button></nav><div class="aside-bottom"><div v-if="authEnabled"><button class="plain" @click="logout">{{ t('Sign out ↗') }}</button></div></div></aside>
  <main class="workspace"><header><span>{{ t('Workspace') }} <span class="muted">/ {{tab==='nodes'?t('Node overview'):t('Enrollment tokens')}}</span></span><span class="muted">{{lastRefresh?t('Updated at {time}', {time: lastRefresh}):''}} <button class="plain" :disabled="busy" @click="refresh">{{busy?t('Refreshing'):t('Refresh ↻')}}</button></span></header>
   <section class="page-heading"><div><p class="eyebrow">EDGE INFRASTRUCTURE</p><h1>{{tab==='nodes'?t('Node overview'):t('Enrollment tokens')}}</h1><p class="muted">{{tab==='nodes'?t('View device identities, networking, and remote management status.'):t('Create enrollment tokens for images, with optional expiry and usage limits.')}}</p></div><span class="pill">{{ t('Check status every {seconds}s', {seconds: interval}) }}</span></section>
   <p v-if="error" role="alert" class="error banner">{{t(error)}}</p>
   <div class="sources"><div v-for="s in sources" :key="s.source"><span :class="['dot',s.state]"></span><strong>{{s.source==='headscale'?'Headscale':'MeshCentral'}}</strong><span>{{text(s.state)}}</span><small v-if="s.last_success">{{ t('Last success') }} {{date(s.last_success)}}</small><small v-if="s.error">{{t(s.error)}}{{ t('; device status may be stale') }}</small></div></div>
   <template v-if="tab==='nodes'">
    <section class="stats"><div><span>{{ t('Registered nodes') }}</span><strong>{{nodes.length}}</strong><small>{{ t('Unique serials') }}</small></div><div><span>{{ t('Last known online') }}</span><strong>{{online}}<i class="dot"></i></strong><small>{{ t('Any channel online · Based on the latest successful sync') }}</small></div><div><span>{{ t('Initialization pending') }}</span><strong>{{unfinished}}</strong><small>{{ t('Open details to see the current step') }}</small></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('Devices') }} <span class="count">{{filtered.length}}</span></h2><input class="search" v-model="query" :placeholder="t('Search serial / Tailscale address')" :aria-label="t('Search nodes')"></div><div class="table-wrap"><table><thead><tr><th>{{ t('Node serial') }}</th><th>{{ t('Network') }}</th><th>{{ t('Remote management') }}</th><th v-if="terminalEnabled">{{ t('Native Agent') }}</th><th>{{ t('Tailscale addresses') }}</th><th>{{ t('Registered at') }}</th><th>{{ t('Initialization') }}</th><th></th></tr></thead><tbody><tr v-for="n in filtered" :key="n.serial"><td><button class="serial plain" @click="selected=n;meshID=''">{{n.serial}}</button></td><td><span :class="['badge',n.headscale_state]">{{text(n.headscale_state)}}</span></td><td><span :class="['badge',n.mesh_state]">{{text(n.mesh_state)}}</span></td><td v-if="terminalEnabled"><span :class="['badge',agents[n.serial]?.online?'online':'offline']">{{agents[n.serial]?.revoked?t('Revoked'):agents[n.serial]?.online?t('Online'):agents[n.serial]?t('Offline'):t('Not enrolled')}}</span></td><td class="mono">{{n.addresses||'—'}}</td><td>{{date(n.created_at)}}</td><td>{{text(n.stage)}}</td><td><button class="plain" @click="selected=n;meshID=''">{{ t('Details ↗') }}</button></td></tr></tbody></table></div><div v-if="!filtered.length" class="empty"><div class="empty-icon">{{ t('▦') }}</div><h3>{{nodes.length?t('No matching nodes'):t('Waiting for the first node')}}</h3><p>{{ t('Create an enrollment token, then run the initializer on a Debian node.') }}</p><button v-if="!nodes.length" class="secondary" @click="tab='tokens'">{{ t('Create enrollment token →') }}</button></div></section>
   </template>
   <template v-else>
    <section class="panel bootstrap-panel"><h2>{{ t('Prepare a factory image') }}</h2><p>{{ t('Run as root on the template and enter the batch token. Then shut down and clone; deployed nodes initialize automatically.') }}</p><template v-if="bootstrapAvailable"><code>{{installCommand}}</code><button class="secondary" @click="copyInstallCommand">{{copied?t('Copied'):t('Copy command')}}</button><p class="muted">{{ t('Requires Debian 13, Python 3, curl, Tailscale, CA certificates, OpenSSH server, and overlayroot. Enrollment automatically enables root OverlayFS and reboots.') }}</p></template><p v-else class="muted">{{ t('Bootstrap downloads are unavailable. Enable bootstrap and deploy its assets before using the installer.') }}</p></section>
    <section class="panel token-form"><h2>{{ t('Create enrollment token') }}</h2><form @submit.prevent="createToken"><label>{{ t('Label') }}<input v-model="tokenLabel" maxlength="120" :placeholder="t('For example: first deployment image')"></label><label>{{ t('Expires at') }} <small>{{ t('Leave blank for no expiry') }}</small><input v-model="expiry" type="datetime-local"></label><label>{{ t('Registration limit') }} <small>{{ t('0 means unlimited') }}</small><input v-model.number="maxUses" type="number" min="0" required></label><button class="primary">{{ t('Generate token') }}</button></form><div v-if="secret" class="secret"><strong>{{ t('Save this token now; it is shown only once') }}</strong><code>{{secret}}</code><button class="plain" @click="secret=''">{{ t('Saved; hide token') }}</button></div></section>
    <section class="panel"><div class="panel-heading"><h2>{{ t('Enrollment token history') }}</h2></div><div class="table-wrap"><table><thead><tr><th>{{ t('Label') }}</th><th>{{ t('Used / limit') }}</th><th>{{ t('Expires at') }}</th><th>{{ t('Status') }}</th><th></th></tr></thead><tbody><tr v-for="token in tokens" :key="token.id"><td>{{token.label||token.id}}</td><td>{{token.uses}} / {{token.max_uses||t('Unlimited')}}</td><td>{{token.expires_at?date(token.expires_at):t('No expiry')}}</td><td>{{token.revoked?t('Revoked'):token.expires_at&&new Date(token.expires_at)<=new Date()?t('Expired'):token.max_uses&&token.uses>=token.max_uses?t('Exhausted'):t('Active')}}</td><td><button v-if="!token.revoked" class="plain danger" @click="revoke(token)">{{ t('Revoke') }}</button></td></tr></tbody></table></div><p v-if="!tokens.length" class="empty">{{ t('No enrollment tokens yet') }}</p></section>
   </template>
   <section v-if="terminalEnabled && tab==='nodes'" class="panel"><div class="panel-heading"><h2>{{ t('Recent terminal sessions') }}</h2></div><div class="table-wrap"><table><thead><tr><th>{{ t('Node') }}</th><th>{{ t('Operator') }}</th><th>{{ t('Requested at') }}</th><th>{{ t('Ended at') }}</th><th>{{ t('End reason') }}</th></tr></thead><tbody><tr v-for="entry in audit" :key="entry.id"><td class="mono">{{entry.serial}}</td><td>{{entry.actor}}</td><td>{{date(entry.created_at)}}</td><td>{{entry.ended_at?date(entry.ended_at):t('In progress')}}</td><td>{{entry.reason||'—'}}</td></tr></tbody></table></div><p v-if="!audit.length" class="empty">{{ t('No terminal sessions yet') }}</p></section>
   <footer>NODE HUB <span>{{ t('Identity registration · Status sync · Remote maintenance') }}</span></footer>
  </main>
  <div v-if="selected" class="modal-backdrop" @click.self="selected=null"><section class="modal" role="dialog" aria-modal="true" :aria-label="t('Node details')"><button class="close plain" @click="selected=null">{{ t('Close ×') }}</button><p class="eyebrow">NODE DETAILS</p><h2 class="mono">{{selected.serial}}</h2><dl><dt>{{ t('Initialization stage') }}</dt><dd>{{text(selected.stage)}}</dd><dt>{{ t('Error summary') }}</dt><dd>{{selected.error||'—'}}</dd><dt>Headscale ID</dt><dd class="mono">{{selected.headscale_id||t('Not bound')}}</dd><dt>{{ t('Network last seen') }}</dt><dd>{{date(selected.headscale_seen)}}</dd><dt>MeshCentral ID</dt><dd class="mono">{{selected.mesh_id||t('Not bound')}}</dd><dt>{{ t('Remote management last seen') }}</dt><dd>{{date(selected.mesh_seen)}}</dd></dl><section v-if="terminalEnabled" class="agent-details"><h3>{{ t('Node Hub native terminal') }}</h3><p class="muted">{{agents[selected.serial]?.revoked?t('Agent revoked'):agents[selected.serial]?.online?t('Agent online'):t('Agent disconnected')}} · {{agents[selected.serial]?.info?.os_version||agents[selected.serial]?.info?.os||'—'}} / {{agents[selected.serial]?.info?.arch||'—'}} · Agent {{agents[selected.serial]?.info?.version||'—'}} · {{ t('Last active') }} {{date(agents[selected.serial]?.last_seen||'')}}</p><button class="primary" :disabled="!agents[selected.serial]?.online || !agents[selected.serial]?.ssh_configured" @click="terminalNode=selected.serial">{{ t('Open SSH terminal') }}</button><button v-if="agents[selected.serial] && !agents[selected.serial]?.revoked" class="plain danger" @click="revokeAgent(selected.serial)">{{ t('Revoke Agent') }}</button><p v-if="!agents[selected.serial]?.ssh_configured" class="muted">{{ t('Automatic SSH provisioning is incomplete. Initialize with --agent-config or retry the original initialization.') }}</p></section><form v-if="!selected.mesh_id" @submit.prevent="bind"><label>{{ t('Confirm MeshCentral binding') }}<input v-model="meshID" placeholder="node/domain/…" required></label><p class="muted">{{ t('Verify the device ID in MeshCentral. The center also checks the device name and configured group.') }}</p><button class="secondary">{{ t('Confirm binding') }}</button></form><a v-if="safeURL(selected.mesh_url)" class="primary link-button" :href="safeURL(selected.mesh_url)" target="_blank" rel="noopener noreferrer">{{ t('Open device in MeshCentral ↗') }}</a><a v-else-if="safeURL(meshURL)" class="secondary link-button" :href="safeURL(meshURL)" target="_blank" rel="noopener noreferrer">{{ t('Open MeshCentral console ↗') }}</a><p v-if="!selected.mesh_url" class="muted">{{ t('Device deep links require validation; use the console entry for now.') }}</p></section></div>
 <TerminalPanel v-if="terminalNode" :serial="terminalNode" @close="terminalNode=''" />
 </div>
</template>
